import { NativeModules, NativeEventEmitter, Platform } from 'react-native';

// Get the native module
const { LinktopHealth } = NativeModules;

// NativeEventEmitter warns unless the native module exposes these no-op methods.
const ensureNativeEventEmitterModule = (
  nativeModule: typeof LinktopHealth,
): typeof LinktopHealth => {
  if (!nativeModule) {
    return nativeModule;
  }
  const emitterModule = nativeModule as typeof LinktopHealth & {
    addListener?: (eventName: string) => void;
    removeListeners?: (count: number) => void;
  };
  if (typeof emitterModule.addListener !== 'function') {
    emitterModule.addListener = () => {};
  }
  if (typeof emitterModule.removeListeners !== 'function') {
    emitterModule.removeListeners = () => {};
  }
  return emitterModule;
};

