  request: EmailOtpLoginOrRegisterRequest,
): Promise<LoginRes | { error: { message: string } }> => {
  try {
    const response = await postRequest<LoginRes>(
      urls.API_EMAIL_OTP_LOGIN_OR_REGISTER,
      request,
    );
    console.log('api emailOtpLoginOrRegister response=', response);
    const payload = response.data;
    if (payload?.success && payload.data?.accessToken) {
      const loginData: LoginData = {
        ...payload.data,
        circle: payload.data.circle ?? { hasSettledPlanPurchase: true },
      };
      getGlobalAppState()?.setLoginData(loginData);
      await AsyncStorage.setItem('memberData', JSON.stringify(loginData));
      await Keychain.setGenericPassword('password', loginData.accessToken);
      return {
        ...payload,
        data: loginData,
      };
    }
    return payload;
  } catch (error) {
    console.log('api emailOtpLoginOrRegister error=', error);
    return {
      error: {
        message: getUnknownErrorMessage(error),
      },
    };
  }
};

