const toLoginError = (error: unknown): LoginError => {
  if (typeof error === 'object' && error !== null && 'error' in error) {
    const nestedError = (error as {error?: unknown}).error;
    if (typeof nestedError === 'object' && nestedError !== null) {
      const message =
        'message' in nestedError && nestedError.message != null
          ? String((nestedError as {message: unknown}).message)
          : getUnknownErrorMessage(error);
      const localizeKey =
        'localize_key' in nestedError && typeof (nestedError as {localize_key?: unknown}).localize_key === 'string'
          ? (nestedError as {localize_key: string}).localize_key
          : undefined;
      return {
        error: {
          message,
          ...(localizeKey ? { localize_key: localizeKey } : {}),
        },
      };
    }
  }
  return {
    error: {
      message: getUnknownErrorMessage(error),
    },
  };
};

