    const pos = d.file.getLineAndCharacterOfPosition(d.start);
    line = pos.line + 1;
    col = pos.character + 1;
  }
  const code = `TS${d.code}`;
  const msg = ts.flattenDiagnosticMessageText(d.messageText, '\n');
  const category = ts.DiagnosticCategory[d.category];
  return `${file}:${line}:${col} ${category} ${code} ${msg}`;
}

const semantic = [];
const syntactic = [];
const suggestion = [];
const coverage = [];

for (const abs of [...changedAbs].sort()) {
  const sf = program.getSourceFile(abs);
  const rel = path.relative(root, abs);
  if (!sf) {
    coverage.push(`${rel} NOT_IN_PROGRAM`);
    continue;
  }
  coverage.push(`${rel} COVERED`);
  syntactic.push(...program.getSyntacticDiagnostics(sf).map(formatDiag));
  semantic.push(...program.getSemanticDiagnostics(sf).map(formatDiag));
  suggestion.push(...program.getSuggestionDiagnostics(sf).map(formatDiag));
}

console.log('=== COVERAGE ===');
console.log(coverage.join('\n'));
console.log('=== SYNTACTIC', syntactic.length, '===');
console.log(syntactic.join('\n') || '(none)');
console.log('=== SEMANTIC', semantic.length, '===');
console.log(semantic.join('\n') || '(none)');
console.log('=== SUGGESTION', suggestion.length, '===');
console.log(suggestion.join('\n') || '(none)');

const globalDiags = ts.getPreEmitDiagnostics(program).filter((d) => {
  if (!d.file) return true;
  return changedAbs.has(path.normalize(d.file.fileName));
});
console.log('=== PREEMIT CHANGED-FILE', globalDiags.length, '===');
console.log(globalDiags.map(formatDiag).join('\n') || '(none)');
